#!/usr/bin/env python3
"""
Check Salesforce CRM availability before looking up an account.

Usage:
    export SF_INSTANCE_URL="https://your-instance.salesforce.com"
    export SF_ACCESS_TOKEN="your-oauth-token"
    python check_crm_account.py "Account Name or ID"
"""

import os
import sys
import requests
import json


def get_env(var: str) -> str:
    val = os.getenv(var)
    if not val:
        sys.exit(f"Missing required environment variable: {var}")
    return val


def check_crm_available(instance_url: str, access_token: str) -> tuple[bool, dict]:
    """
    Check Salesforce CRM availability via the Limits API (lightweight health check).
    Returns (is_available, response_data).
    """
    url = f"{instance_url.rstrip('/')}/services/data/v60.0/limits"
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/json",
    }
    try:
        resp = requests.get(url, headers=headers, timeout=10)
        if resp.status_code == 200:
            return True, resp.json()
        elif resp.status_code == 401:
            return False, {"error": "Authentication failed - token may be expired"}
        else:
            return False, {"error": f"HTTP {resp.status_code}: {resp.text}"}
    except requests.exceptions.Timeout:
        return False, {"error": "Request timed out - CRM may be unreachable"}
    except requests.exceptions.ConnectionError:
        return False, {"error": "Connection failed - check network/instance URL"}
    except Exception as e:
        return False, {"error": f"Unexpected error: {e}"}


def lookup_account(instance_url: str, access_token: str, account_identifier: str) -> dict:
    """
    Look up an account by Name or Id.
    Tries exact Id match first, then Name search via SOQL.
    """
    headers = {
        "Authorization": f"Bearer {access_token}",
        "Content-Type": "application/json",
    }

    # If it looks like an 18-char Salesforce Id, query directly
    if len(account_identifier) in (15, 18) and account_identifier.startswith("001"):
        url = f"{instance_url.rstrip('/')}/services/data/v60.0/sobjects/Account/{account_identifier}"
        resp = requests.get(url, headers=headers, timeout=10)
        if resp.status_code == 200:
            return resp.json()
        elif resp.status_code == 404:
            return {"error": "Account not found"}
        else:
            return {"error": f"HTTP {resp.status_code}: {resp.text}"}

    # Otherwise search by Name via SOQL
    soql = f"SELECT Id, Name, Type, Industry, Phone, Website, BillingCity, BillingState, BillingCountry FROM Account WHERE Name = '{account_identifier}' LIMIT 1"
    url = f"{instance_url.rstrip('/')}/services/data/v60.0/query/?q={requests.utils.quote(soql)}"
    resp = requests.get(url, headers=headers, timeout=10)
    if resp.status_code == 200:
        data = resp.json()
        if data["totalSize"] == 0:
            return {"error": f"No account found with name '{account_identifier}'"}
        return data["records"][0]
    else:
        return {"error": f"HTTP {resp.status_code}: {resp.text}"}


def main():
    if len(sys.argv) < 2:
        sys.exit("Usage: python check_crm_account.py '<Account Name or ID>'")

    account_identifier = sys.argv[1]

    instance_url = get_env("SF_INSTANCE_URL")
    access_token = get_env("SF_ACCESS_TOKEN")

    print(f"🔍 Checking CRM availability at {instance_url}...")
    available, health = check_crm_available(instance_url, access_token)

    if not available:
        print(f"❌ CRM UNAVAILABLE: {health.get('error', 'Unknown error')}")
        sys.exit(1)

    print("✅ CRM is available (Limits API responded successfully)")
    print(f"   Daily API requests used: {health.get('DailyApiRequests', {}).get('Remaining', 'N/A')} remaining")

    print(f"\n🔍 Looking up account: {account_identifier}")
    account = lookup_account(instance_url, access_token, account_identifier)

    if "error" in account:
        print(f"❌ Account lookup failed: {account['error']}")
        sys.exit(1)

    print("\n✅ Account found:")
    print(json.dumps(account, indent=2))


if __name__ == "__main__":
    main()

